const input = $json ?? {};
const body = input.body ?? {};

const defaults = {
  // The LinkedIn search URL behind each RSS feed already represents
  // the actual search criteria. We do not filter jobs again by keyword in n8n.
  keywords: [],

  // Maximum job age used by downstream normalization logic.
  max_age_hours: 24,

  // FetchRSS Free currently supports up to 5 feeds.
  // Replace only the placeholders you want to use.
  // Unconfigured placeholder feeds are automatically ignored.
  rss_feeds: [
    {
      url: 'YOUR_FETCHRSS_FEED_URL_1',
      source: 'FetchRSS',
      search_keyword: 'YOUR_SEARCH_KEYWORD_1',
      location: '',
      work_mode: ''
    },
    {
      url: 'YOUR_FETCHRSS_FEED_URL_2',
      source: 'FetchRSS',
      search_keyword: 'YOUR_SEARCH_KEYWORD_2',
      location: '',
      work_mode: ''
    },
    {
      url: 'YOUR_FETCHRSS_FEED_URL_3',
      source: 'FetchRSS',
      search_keyword: 'YOUR_SEARCH_KEYWORD_3',
      location: '',
      work_mode: ''
    },
    {
      url: 'YOUR_FETCHRSS_FEED_URL_4',
      source: 'FetchRSS',
      search_keyword: 'YOUR_SEARCH_KEYWORD_4',
      location: '',
      work_mode: ''
    },
    {
      url: 'YOUR_FETCHRSS_FEED_URL_5',
      source: 'FetchRSS',
      search_keyword: 'YOUR_SEARCH_KEYWORD_5',
      location: '',
      work_mode: ''
    }
  ]
};


function normalizeKeywords(value) {
  if (Array.isArray(value)) {
    return value
      .map(String)
      .map(v => v.trim())
      .filter(Boolean);
  }

  if (typeof value === 'string') {
    return value
      .split(',')
      .map(v => v.trim())
      .filter(Boolean);
  }

  return [];
}


function normalizeFeeds(value) {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map(feed => ({
      url: String(feed?.url ?? '').trim(),
      source: String(feed?.source ?? 'FetchRSS').trim() || 'FetchRSS',
      search_keyword: String(feed?.search_keyword ?? '').trim(),
      location: String(feed?.location ?? '').trim(),
      work_mode: String(feed?.work_mode ?? '').trim()
    }))
    .filter(feed => {
      if (!feed.url) {
        return false;
      }

      // Ignore public-template placeholders that were not configured yet.
      return !feed.url.startsWith('YOUR_FETCHRSS_FEED_URL_');
    });
}


const requestedKeywords =
  normalizeKeywords(body.keywords).length
    ? normalizeKeywords(body.keywords)
    : normalizeKeywords(defaults.keywords);


const requestedMaxAge =
  Number(
    body.max_age_hours ??
    defaults.max_age_hours
  );


const requestedFeeds =
  normalizeFeeds(body.rss_feeds).length
    ? normalizeFeeds(body.rss_feeds)
    : normalizeFeeds(defaults.rss_feeds);


if (!requestedFeeds.length) {
  throw new Error(
    'No RSS feeds are configured. Replace at least one YOUR_FETCHRSS_FEED_URL_X placeholder with a valid FetchRSS feed URL.'
  );
}


return [{
  json: {
    keywords: requestedKeywords,

    max_age_hours:
      Number.isFinite(requestedMaxAge) &&
      requestedMaxAge > 0
        ? requestedMaxAge
        : 24,

    rss_feeds: requestedFeeds
  }
}];

const cfg = $input.first().json ?? {};

const feeds = Array.isArray(cfg.rss_feeds)
  ? cfg.rss_feeds
      .map(feed => {
        const url = String(feed?.url ?? '').trim();

        return {
          url,

          source:
            String(feed?.source ?? '').trim() ||
            'FetchRSS',

          search_keyword:
            String(feed?.search_keyword ?? '').trim(),

          location:
            String(feed?.location ?? '').trim(),

          work_mode:
            String(feed?.work_mode ?? '').trim()
        };
      })
      .filter(feed => {
        // Only keep valid HTTP/HTTPS feed URLs.
        if (!/^https?:\/\//i.test(feed.url)) {
          return false;
        }

        // Ignore public-template placeholders that were not configured.
        if (feed.url.startsWith('YOUR_FETCHRSS_FEED_URL_')) {
          return false;
        }

        return true;
      })
  : [];


if (!feeds.length) {
  throw new Error(
    'No valid RSS feeds were received from Resolve Search Plan. Configure at least one FetchRSS feed before running the workflow.'
  );
}


return feeds.map(feed => ({
  json: {
    feed_url: feed.url,

    source: feed.source,

    search_keyword: feed.search_keyword,

    default_location: feed.location,

    default_work_mode: feed.work_mode,

    keywords:
      Array.isArray(cfg.keywords)
        ? cfg.keywords
        : [],

    max_age_hours:
      Number.isFinite(Number(cfg.max_age_hours)) &&
      Number(cfg.max_age_hours) > 0
        ? Number(cfg.max_age_hours)
        : 24
  }
}));

const ctx = $('Loop RSS Feeds').item.json ?? {};

// Public template default.
// Change this value if you want spreadsheet timestamps
// formatted in a specific local timezone.
const DEFAULT_TIME_ZONE = 'UTC';


function clean(value) {
  if (value === null || value === undefined) {
    return '';
  }

  return String(value)
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/\s+/g, ' ')
    .trim();
}


function cleanUrl(raw) {
  if (!raw) {
    return '';
  }

  try {
    const decoded = String(raw)
      .replace(/&amp;/g, '&');

    const url = new URL(decoded);

    // Keep LinkedIn job URLs clean while preserving
    // the path that contains the job identifier.
    if (
      /linkedin\.com$/i.test(url.hostname) ||
      /\.linkedin\.com$/i.test(url.hostname)
    ) {
      return (
        `${url.protocol}//${url.hostname}${url.pathname}`
      ).replace(/\/$/, '');
    }

    url.hash = '';
    url.search = '';

    return url
      .toString()
      .replace(/\/$/, '');

  } catch {
    return String(raw)
      .replace(/&amp;/g, '&')
      .split('?')[0]
      .split('#')[0]
      .trim();
  }
}


function jobIdFromUrl(url) {
  const value = String(url || '');

  const match =
    value.match(
      /\/jobs\/view\/(?:[^/?#]*-)?(\d+)(?:[/?#]|$)/i
    ) ||
    value.match(
      /\/jobs\/view\/(\d+)/i
    );

  return match?.[1] || `url:${value}`;
}


/*
  Returns:

  DD/MM/YYYY HH:mm

  without seconds.
*/
function formatDateTime(
  value,
  timeZone = DEFAULT_TIME_ZONE
) {
  const date =
    value instanceof Date
      ? value
      : new Date(value);

  if (Number.isNaN(date.getTime())) {
    return '';
  }

  const parts =
    new Intl.DateTimeFormat(
      'en-US',
      {
        timeZone,

        day: '2-digit',
        month: '2-digit',
        year: 'numeric',

        hour: '2-digit',
        minute: '2-digit',

        hour12: false
      }
    )
      .formatToParts(date)
      .reduce((acc, part) => {
        acc[part.type] = part.value;
        return acc;
      }, {});

  return (
    `${parts.day}/` +
    `${parts.month}/` +
    `${parts.year} ` +
    `${parts.hour}:` +
    `${parts.minute}`
  );
}


function detectLanguage(title) {
  const text = String(title || '')
    .toLowerCase();

  const portuguese =
    /\b(engenheiro|engenheira|engenharia|desenvolvedor|desenvolvedora|analista|especialista|inteligência|dados|automação|remoto|remota|estágio|estagiário|estagiária|sênior|pleno|júnior)\b/i;

  const english =
    /\b(engineer|developer|analyst|specialist|intelligence|automation|remote|software|machine learning|data)\b/i;

  if (portuguese.test(text)) {
    return 'Portuguese';
  }

  if (english.test(text)) {
    return 'English';
  }

  return '';
}


function detectTimeType(text) {
  const value = String(text || '')
    .toLowerCase();

  if (
    /\bpart[- ]?time\b|\bmeio período\b/i.test(value)
  ) {
    return 'Part-time';
  }

  if (
    /\bfull[- ]?time\b|\btempo integral\b/i.test(value)
  ) {
    return 'Full-time';
  }

  return '';
}


function detectJobType(text) {
  const value = String(text || '')
    .toLowerCase();

  const types = [];

  if (
    /\bcontract\b|\bcontractor\b|\bcontrato\b/i.test(value)
  ) {
    types.push('Contract');
  }

  if (
    /\binternship\b|\bestágio\b|\bestagiário\b|\bestagiária\b/i.test(value)
  ) {
    types.push('Internship');
  }

  if (
    /\bfreelance\b|\bfreelancer\b/i.test(value)
  ) {
    types.push('Freelance');
  }

  if (
    /\btemporary\b|\btemporário\b|\btemporária\b/i.test(value)
  ) {
    types.push('Temporary');
  }

  if (
    /\bpj\b|\bpessoa jurídica\b/i.test(value)
  ) {
    types.push('PJ');
  }

  if (
    /\bclt\b/i.test(value)
  ) {
    types.push('CLT');
  }

  if (
    /\blong[- ]?term\b|\blongo prazo\b/i.test(value)
  ) {
    types.push('Long-term');
  }

  return [...new Set(types)]
    .join(', ');
}


function detectExperience(title) {
  const value = String(title || '')
    .toLowerCase();

  // Detect combined Mid/Senior titles before
  // checking each level individually.
  if (
    (
      /\bpleno\b|\bmid[- ]?level\b|\bmid\b/i.test(value)
    ) &&
    (
      /\bsenior\b|\bsênior\b|\bsr\.?\b/i.test(value)
    )
  ) {
    return 'Mid, Senior';
  }

  if (
    /\blead\b|\blíder\b|\blider\b/i.test(value)
  ) {
    return 'Lead';
  }

  if (
    /\bsenior\b|\bsênior\b|\bsr\.?\b/i.test(value)
  ) {
    return 'Senior';
  }

  if (
    /\bspecialist\b|\bespecialista\b/i.test(value)
  ) {
    return 'Specialist';
  }

  if (
    /\bpleno\b|\bmid[- ]?level\b|\bmid\b/i.test(value)
  ) {
    return 'Mid';
  }

  if (
    /\bjunior\b|\bjúnior\b|\bjr\.?\b|\bentry[- ]?level\b|\bassistente\b/i.test(value)
  ) {
    return 'Junior';
  }

  if (
    /\bintern\b|\binternship\b|\bestagi[aá]ri[oa]\b/i.test(value)
  ) {
    return 'Intern';
  }

  return '';
}


/*
  FetchRSS can expose location information through
  the RSS summary/content fields.

  Provider boilerplate is removed before the value
  is stored as the geographic job location.
*/
function extractLocation(item) {
  const raw =
    item.contentSnippet ??
    item.description ??
    item.summary ??
    item.content ??
    '';

  return clean(raw)
    .replace(
      /\(?\s*Feed generated with FetchRSS\s*\)?/gi,
      ''
    )
    .trim();
}


const jobs = [];


for (const input of $input.all()) {
  const item = input.json ?? {};


  const rawUrl =
    item.link ??
    item.origLink ??
    item.guid ??
    item.url ??
    '';


  const url =
    cleanUrl(rawUrl);


  // Only LinkedIn job URLs are accepted.
  if (
    !/linkedin\.com\/jobs\//i.test(url)
  ) {
    continue;
  }


  const published =
    item.isoDate ??
    item.pubDate ??
    item.published ??
    item.updated ??
    '';


  const publishedMs =
    Date.parse(published);


  if (
    Number.isNaN(publishedMs)
  ) {
    continue;
  }


  /*
    Job age is not filtered again here.

    The LinkedIn search used to generate each RSS feed
    should already contain the desired recency filter.

    Duplicate protection is handled downstream using
    the LinkedIn Job ID.
  */


  const title =
    clean(item.title) ||
    'Not specified';


  const companyName =
    clean(
      item.creator ??
      item['dc:creator'] ??
      item.author ??
      item.company ??
      ''
    );


  const extractedLocation =
    extractLocation(item);


  /*
    Geographic location can come directly from the RSS feed.

    A configured default_location may optionally override it
    when a feed represents a fixed geographic search.
  */
  const location =
    clean(ctx.default_location) ||
    extractedLocation;


  /*
    Work Mode is metadata configured for each feed.

    Supported values:
    Remote, Hybrid, On-site.

    If the feed configuration does not explicitly provide
    one of these values, the field remains empty.
  */
  const workMode =
    [
      'Remote',
      'Hybrid',
      'On-site'
    ].includes(
      String(
        ctx.default_work_mode ?? ''
      ).trim()
    )
      ? String(
          ctx.default_work_mode
        ).trim()
      : '';


  /*
    This text is used only for deterministic first-pass
    field detection.

    It is not stored as the final job description because
    RSS feeds may not contain the full LinkedIn description.
  */
  const sourceText =
    [
      title,
      companyName,
      extractedLocation
    ]
      .filter(Boolean)
      .join(' ');


  const scrapedNow =
    new Date();


  jobs.push({

    // A - Job ID
    job_id:
      jobIdFromUrl(url),

    // B - Status
    status:
      'To do',

    // C - Date Scraped
    date_scraped:
      formatDateTime(
        scrapedNow
      ),

    // D - Source
    source:
      ctx.source ||
      'FetchRSS',

    // E - Search Keyword
    search_keyword:
      ctx.search_keyword ||
      '',

    // F - Date Posted
    date_posted:
      formatDateTime(
        new Date(publishedMs)
      ),

    // G - Title
    title,

    // H - Work Mode
    work_mode:
      workMode,

    // I - URL
    url,

    // J - Company Name
    company_name:
      companyName,

    // K - Location
    location,

    // L - Description
    description:
      '',

    // M - Language
    language:
      detectLanguage(title),

    // N - Payment
    payment:
      '',

    // O - Time Type
    time_type:
      detectTimeType(sourceText),

    // P - Job Type
    job_type:
      detectJobType(sourceText),

    // Q - Experience
    experience:
      detectExperience(title),

    // R - Salary
    salary:
      '',

    // S - Match
    match:
      '',

    // T - Qualified
    qualified:
      '',

    // U - Cover Letter
    cover_letter:
      '',

    // V - Notes
    notes:
      '',

    // W - Interview At
    interview_at:
      '',

    // X - Invite Meet
    invite_meet:
      '',

    // Y - Attended
    attended:
      false,


    // Internal workflow metadata

    posted_at:
      new Date(
        publishedMs
      ).toISOString(),

    scraped_at:
      scrapedNow.toISOString(),

    _feed_url:
      ctx.feed_url
  });
}


return [{
  json: {
    feed_url:
      ctx.feed_url,

    source:
      ctx.source ||
      'FetchRSS',

    search_keyword:
      ctx.search_keyword ||
      '',

    jobs
  }
}];

const feedResults =
  $input.all().map(item => item.json ?? {});

const allJobs = [];

for (const result of feedResults) {
  const jobs =
    Array.isArray(result.jobs)
      ? result.jobs
      : [];

  allJobs.push(...jobs);
}

return [{
  json: {
    jobs: allJobs,
    rss_feed_count: feedResults.length,
    raw_job_count: allJobs.length
  }
}];

const jobs = Array.isArray($json.jobs)
  ? $json.jobs
  : [];

const seen = new Map();


function completeness(job) {
  const fields = [
    'title',
    'work_mode',
    'company_name',
    'location',
    'description',
    'language',
    'payment',
    'time_type',
    'job_type',
    'experience',
    'salary'
  ];

  return fields.reduce((score, field) => {
    const value = String(
      job?.[field] ?? ''
    ).trim();

    return score + (value ? 1 : 0);
  }, 0);
}


for (const job of jobs) {
  if (!job) {
    continue;
  }

  const key = String(
    job.job_id ??
    job.url ??
    ''
  ).trim();

  if (!key) {
    continue;
  }


  // Keep the first occurrence of each unique job.
  if (!seen.has(key)) {
    seen.set(key, job);
    continue;
  }


  const current =
    seen.get(key);


  /*
    If the same LinkedIn job appears in multiple feeds,
    keep the version with the highest number of populated
    fields.

    This lets overlapping search feeds improve discovery
    coverage without creating duplicate jobs downstream.
  */
  if (
    completeness(job) >
    completeness(current)
  ) {
    seen.set(key, job);
  }
}


return [...seen.values()]
  .map(job => ({
    json: job
  }));

return [{
  json: {
    status: 'completed',
    source: 'rss',
    message: 'RSS search completed.'
  }
}];
